use super::*;

#[test]
fn every_upstream_assertion_case_matches_the_complete_result() {
    // Generated by executing every original assertion, then recording the full
    // output. Compare more than the original partial assertions, never less.
    let mut count = 0;
    for line in include_str!("win32_upstream_cases.tsv").lines() {
        let p: Vec<_> = line.split('\t').collect();
        assert_eq!(p.len(), 7);
        let key: Vec<u16> = p[1]
            .split(',')
            .filter(|s| !s.is_empty())
            .map(|s| u16::from_str_radix(s, 16).unwrap())
            .collect();
        let flags: u8 = p[3].parse().unwrap();
        let code: Vec<_> = p[0].encode_utf16().collect();
        let event = Win32KeyboardEvent {
            code: &code,
            key: &key,
            key_code: p[2].parse().unwrap(),
            alt_key: flags & 1 != 0,
            ctrl_key: flags & 2 != 0,
            shift_key: flags & 4 != 0,
            meta_key: flags & 8 != 0,
        };
        let result = Win32InputMode.evaluate_keyboard_event(&event, p[4] == "1");
        assert_eq!(result.result_type, KeyboardResultType::SendKey, "{}", p[6]);
        assert!(result.cancel, "{}", p[6]);
        assert_eq!(
            result.key,
            Some(format!("\x1b[{}", p[5]).encode_utf16().collect()),
            "{}",
            p[6]
        );
        count += 1;
    }
    assert_eq!(count, 64, "upstream case count must not shrink silently");
}

fn encode(key: &[u16], ctrl: bool, alt: bool, meta: bool) -> String {
    let result = Win32InputMode.evaluate_keyboard_event(
        &Win32KeyboardEvent {
            key,
            ctrl_key: ctrl,
            alt_key: alt,
            meta_key: meta,
            ..Default::default()
        },
        true,
    );
    String::from_utf16(&result.key.unwrap()).unwrap()
}

#[test]
fn javascript_utf16_length_is_not_rust_character_count() {
    assert_eq!(
        encode(&[0xd83d, 0xde00], false, false, false),
        "\x1b[0;0;0;1;0;1_"
    );
    assert_eq!(
        encode(&[0xd800], false, false, false),
        "\x1b[0;0;55296;1;0;1_"
    );
    assert_eq!(
        encode(&[0xdfff], false, false, false),
        "\x1b[0;0;57343;1;0;1_"
    );
    assert_eq!(encode(&[], false, false, false), "\x1b[0;0;0;1;0;1_");
}

#[test]
fn alt_and_meta_prevent_ctrl_character_conversion() {
    for (key, normal, controlled) in [("Enter", 13, 10), ("Backspace", 8, 127), ("c", 99, 3)] {
        let key: Vec<_> = key.encode_utf16().collect();
        assert_eq!(
            encode(&key, true, false, false),
            format!("\x1b[0;0;{controlled};1;8;1_")
        );
        assert_eq!(
            encode(&key, true, true, false),
            format!("\x1b[0;0;{normal};1;10;1_")
        );
        assert_eq!(
            encode(&key, true, false, true),
            format!("\x1b[0;0;{normal};1;8;1_")
        );
    }
}

#[test]
fn unknown_code_uses_key_code_without_inventing_a_scan_code() {
    let event = Win32KeyboardEvent {
        code: &[85, 110, 109, 97, 112, 112, 101, 100],
        key_code: u32::MAX,
        ..Default::default()
    };
    assert_eq!(
        Win32InputMode.evaluate_keyboard_event(&event, false).key,
        Some("\x1b[4294967295;0;0;0;0;1_".encode_utf16().collect())
    );
}
